From fc06864b9e0a2509b60dd24273ad170368c45d9c Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 22:28:14 +0100
Subject: [PATCH] kded: add shortcuts to change the volume of all output
 devices

The volume keys only ever change the preferred output device, so people
with several devices in use at once have to adjust each one by hand. Add
"Increase/Decrease Volume of All Output Devices" actions without keys.

BUG: 372016
---
 src/kded/audioshortcutsservice.cpp | 37 ++++++++++++++++++++++++++++++
 src/kded/audioshortcutsservice.h   |  1 +
 2 files changed, 38 insertions(+)

diff --git a/src/kded/audioshortcutsservice.cpp b/src/kded/audioshortcutsservice.cpp
index b7e42fa2..897e5d00 100644
--- a/src/kded/audioshortcutsservice.cpp
+++ b/src/kded/audioshortcutsservice.cpp
@@ -135,6 +135,22 @@ AudioShortcutsService::AudioShortcutsService(QObject *parent, const QList<QVaria
         playFeedback(-1);
     });

+    QAction *volumeUpAllAction = new QAction(this);
+    actions.append(volumeUpAllAction);
+    volumeUpAllAction->setObjectName(u"increase_volume_all_devices"_s);
+    volumeUpAllAction->setText(i18n("Increase Volume of All Output Devices"));
+    connect(volumeUpAllAction, &QAction::triggered, this, [this]() {
+        changeAllSinksVolumePercent(m_globalConfig->volumeStep());
+    });
+
+    QAction *volumeDownAllAction = new QAction(this);
+    actions.append(volumeDownAllAction);
+    volumeDownAllAction->setObjectName(u"decrease_volume_all_devices"_s);
+    volumeDownAllAction->setText(i18n("Decrease Volume of All Output Devices"));
+    connect(volumeDownAllAction, &QAction::triggered, this, [this]() {
+        changeAllSinksVolumePercent(-m_globalConfig->volumeStep());
+    });
+
     QAction *volumeUpMicAction = new QAction(this);
     actions.append(volumeUpMicAction);
     volumeUpMicAction->setObjectName(u"increase_microphone_volume"_s);
@@ -245,6 +261,27 @@ int AudioShortcutsService::changeVolumePercent(PulseAudioQt::Device *device, int
     return newPercent;
 }

+void AudioShortcutsService::changeAllSinksVolumePercent(int deltaPercent)
+{
+    const auto preferredSink = m_preferredDevice.sink();
+    int preferredPercent = -1;
+    const auto sinks = PulseAudioQt::Context::instance()->sinks();
+    for (PulseAudioQt::Sink *sink : sinks) {
+        if (sink->name() == DUMMY_OUTPUT_NAME) {
+            continue;
+        }
+        const int percent = changeVolumePercent(sink, deltaPercent);
+        if (sink == preferredSink) {
+            preferredPercent = percent;
+        }
+    }
+    if (preferredPercent < 0) {
+        return;
+    }
+    showVolume(preferredPercent);
+    playFeedback(-1);
+}
+
 void AudioShortcutsService::handleDefaultSinkChange()
 {
     const PulseAudioQt::Sink *defaultSink = PulseAudioQt::Context::instance()->server()->defaultSink();
diff --git a/src/kded/audioshortcutsservice.h b/src/kded/audioshortcutsservice.h
index 26cf38d8..15425fe6 100644
--- a/src/kded/audioshortcutsservice.h
+++ b/src/kded/audioshortcutsservice.h
@@ -54,6 +54,7 @@ private:
     static qint64 boundVolume(qint64 volume, int maxVolume);
     static int volumePercent(qint64 volume);
     int changeVolumePercent(PulseAudioQt::Device *device, int deltaPercent);
+    void changeAllSinksVolumePercent(int deltaPercent);
     void handleDefaultSinkChange();
     void muteVolume();
     void playFeedback(int sinkIdx);
